def get_kvs(account_id, namespace_title=None, namespace_id=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0339000" if __import__("os").path.isdir("./environment_mix/0339000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        # opaque but we use base64url(json)
        try:
            pad = "=" * ((4 - (len(cur) % 4)) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("utf-8"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            off = obj.get("offset")
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    def _make_cursor(offset):
        payload = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    start = time.time()
    ops = _load("mcp_operations.json")
    accounts = _load("cf_accounts.json")

    # Resolve account context first; fail UNAUTHORIZED only if no active account can serve this request.
    acct = None
    if isinstance(account_id, str):
        for a in accounts:
            if a.get("id") == account_id:
                acct = a
                break

    # Create operation row (must exist for every call)
    op_id = "mcop_" + base64.urlsafe_b64encode(os.urandom(18)).decode("utf-8").rstrip("=")
    now = _now()
    op_row = {
        "id": op_id,
        "account_id": account_id if isinstance(account_id, str) else "",
        "tool_name": "get_kvs",
        "status": "received",
        "request_json": {
            "account_id": account_id,
            "namespace_title": namespace_title,
            "namespace_id": namespace_id,
            "status": status,
            "limit": limit,
            "cursor": cursor,
            "sort": sort,
            "order": order,
        },
        "response_json": None,
        "error_message": None,
        "http_status": None,
        "resource_type": "kv",
        "resource_locator": None,
        "duration_ms": None,
        "idempotency_key": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op_row)
    _save("mcp_operations.json", ops)

    def _finish_ok(resp, http_status=200):
        ops2 = _load("mcp_operations.json")
        for r in ops2:
            if r.get("id") == op_id:
                r["status"] = "succeeded"
                r["http_status"] = http_status
                r["response_json"] = resp if isinstance(resp, dict) else {"result": resp}
                r["updated_at"] = _now()
                r["duration_ms"] = int((time.time() - start) * 1000)
                break
        _save("mcp_operations.json", ops2)
        return resp

    def _finish_err(code, msg, http_status=400, **x):
        err = _err(code, msg, **x)
        ops2 = _load("mcp_operations.json")
        for r in ops2:
            if r.get("id") == op_id:
                r["status"] = "failed"
                r["http_status"] = http_status
                r["error_message"] = msg
                r["response_json"] = {"error": err["error"]}
                r["updated_at"] = _now()
                r["duration_ms"] = int((time.time() - start) * 1000)
                break
        _save("mcp_operations.json", ops2)
        return err

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^cfacct_[0-9A-Z]{18,}$", account_id):
        return _finish_err("VALIDATION_ERROR", "account_id is invalid; expected pattern ^cfacct_[0-9A-Z]{18,}$", 400)

    if namespace_title is not None and not isinstance(namespace_title, str):
        return _finish_err("VALIDATION_ERROR", "namespace_title must be a string", 400)
    if namespace_id is not None and not isinstance(namespace_id, str):
        return _finish_err("VALIDATION_ERROR", "namespace_id must be a string", 400)
    if status is not None:
        if not isinstance(status, str) or status not in ("present", "deleted"):
            return _finish_err("VALIDATION_ERROR", "status must be one of: present, deleted", 400)
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        return _finish_err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000", 400)
    if cursor is not None and not isinstance(cursor, str):
        return _finish_err("VALIDATION_ERROR", "cursor must be a string", 400)
    if sort is None:
        sort = "updated_at"
    if not isinstance(sort, str) or sort not in ("namespace_title", "namespace_id", "last_seen_at", "updated_at", "created_at"):
        return _finish_err("VALIDATION_ERROR", "sort must be one of: namespace_title, namespace_id, last_seen_at, updated_at, created_at", 400)
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        return _finish_err("VALIDATION_ERROR", "order must be one of: asc, desc", 400)

    if acct is None:
        return _finish_err("NOT_FOUND", "account_id not found", 404)

    if acct.get("status") != "active":
        return _finish_err("UNAUTHORIZED", "account connection is not active", 401)

    offset = _parse_cursor(cursor)
    if cursor is not None and offset is None:
        return _finish_err("VALIDATION_ERROR", "cursor is invalid", 400)
    if offset is None:
        offset = 0

    kv = _load("cf_kv_namespaces_and_keys.json")

    rows = []
    for r in kv:
        if r.get("account_id") != account_id:
            continue
        if namespace_title is not None and r.get("namespace_title") != namespace_title:
            continue
        if namespace_id is not None and r.get("namespace_id") != namespace_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        rows.append(r)

    def _dt_key(v):
        # Sort with None last for asc, first for desc (by using tuple)
        if v is None:
            return (1, "")
        if not isinstance(v, str):
            return (0, str(v))
        return (0, v)

    reverse = (order == "desc")
    rows.sort(key=lambda r: _dt_key(r.get(sort)), reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    resp = {
        "result": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order,
        },
    }
    return _finish_ok(resp, 200)

def kv_put(account_id, namespace_id, key, value, encoding=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0339000" if __import__("os").path.isdir("./environment_mix/0339000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    start = time.time()
    ops = _load("mcp_operations.json")
    accounts = _load("cf_accounts.json")

    acct = None
    if isinstance(account_id, str):
        for a in accounts:
            if a.get("id") == account_id:
                acct = a
                break

    op_id = "mcop_" + base64.urlsafe_b64encode(os.urandom(18)).decode("utf-8").rstrip("=")
    now = _now()
    op_row = {
        "id": op_id,
        "account_id": account_id if isinstance(account_id, str) else "",
        "tool_name": "kv_put",
        "status": "received",
        "request_json": {
            "account_id": account_id,
            "namespace_id": namespace_id,
            "key": key,
            "encoding": encoding,
            # omit large value; include hash
            "value_sha256": hashlib.sha256(value.encode("utf-8")).hexdigest() if isinstance(value, str) else None,
            "value_length": len(value) if isinstance(value, str) else None,
        },
        "response_json": None,
        "error_message": None,
        "http_status": None,
        "resource_type": "kv",
        "resource_locator": f"{namespace_id}:{key}" if isinstance(namespace_id, str) and isinstance(key, str) else None,
        "duration_ms": None,
        "idempotency_key": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op_row)
    _save("mcp_operations.json", ops)

    def _finish_ok(resp, http_status=200):
        ops2 = _load("mcp_operations.json")
        for r in ops2:
            if r.get("id") == op_id:
                r["status"] = "succeeded"
                r["http_status"] = http_status
                r["response_json"] = resp if isinstance(resp, dict) else {"result": resp}
                r["updated_at"] = _now()
                r["duration_ms"] = int((time.time() - start) * 1000)
                break
        _save("mcp_operations.json", ops2)
        return resp

    def _finish_err(code, msg, http_status=400, **x):
        err = _err(code, msg, **x)
        ops2 = _load("mcp_operations.json")
        for r in ops2:
            if r.get("id") == op_id:
                r["status"] = "failed"
                r["http_status"] = http_status
                r["error_message"] = msg
                r["response_json"] = {"error": err["error"]}
                r["updated_at"] = _now()
                r["duration_ms"] = int((time.time() - start) * 1000)
                break
        _save("mcp_operations.json", ops2)
        return err

    # Validate
    if not isinstance(account_id, str) or not re.match(r"^cfacct_[0-9A-Z]{18,}$", account_id):
        return _finish_err("VALIDATION_ERROR", "account_id is invalid; expected pattern ^cfacct_[0-9A-Z]{18,}$", 400)
    if not isinstance(namespace_id, str) or not namespace_id:
        return _finish_err("VALIDATION_ERROR", "namespace_id is required", 400)
    if not isinstance(key, str) or not key:
        return _finish_err("VALIDATION_ERROR", "key is required", 400)
    if not isinstance(value, str):
        return _finish_err("VALIDATION_ERROR", "value must be a string", 400)
    if encoding is None:
        encoding = "utf8"
    if not isinstance(encoding, str) or encoding not in ("utf8", "base64", "json"):
        return _finish_err("VALIDATION_ERROR", "encoding must be one of: utf8, base64, json", 400)

    if acct is None:
        return _finish_err("NOT_FOUND", "account_id not found", 404)
    if acct.get("status") != "active":
        return _finish_err("UNAUTHORIZED", "account connection is not active", 401)

    # Validate encoding payload
    normalized_value_to_cache = None
    cache_encoding = encoding
    try:
        if encoding == "utf8":
            normalized_value_to_cache = value
        elif encoding == "base64":
            # must be valid base64
            base64.b64decode(value.encode("utf-8"), validate=True)
            normalized_value_to_cache = value
        elif encoding == "json":
            # must be valid JSON; cache as minified JSON string
            obj = json.loads(value)
            normalized_value_to_cache = json.dumps(obj, ensure_ascii=False, separators=(",", ":"))
    except Exception:
        return _finish_err("VALIDATION_ERROR", f"value is invalid for encoding '{encoding}'", 400)

    kv = _load("cf_kv_namespaces_and_keys.json")
    now2 = _now()

    # Upsert by unique(account_id, namespace_id, key)
    row = None
    for r in kv:
        if r.get("account_id") == account_id and r.get("namespace_id") == namespace_id and r.get("key") == key:
            row = r
            break

    if row is None:
        new_id = "cfkv_" + base64.urlsafe_b64encode(os.urandom(18)).decode("utf-8").rstrip("=")
        row = {
            "id": new_id,
            "account_id": account_id,
            "namespace_id": namespace_id,
            "namespace_title": None,
            "key": key,
            "status": "present",
            "last_seen_at": now2,
            "cached_value": None,
            "cached_value_encoding": None,
            "cached_value_bytes": None,
            "created_at": now2,
            "updated_at": now2,
        }
        kv.append(row)
    else:
        # If it was deleted, transition deleted->present is allowed
        row["status"] = "present"
        row["last_seen_at"] = now2
        row["updated_at"] = now2

    # Cache only if <= 65536 bytes
    value_bytes = len(normalized_value_to_cache.encode("utf-8"))
    if value_bytes <= 65536:
        row["cached_value"] = normalized_value_to_cache
        row["cached_value_encoding"] = cache_encoding
        row["cached_value_bytes"] = value_bytes
    else:
        row["cached_value"] = None
        row["cached_value_encoding"] = None
        row["cached_value_bytes"] = None

    _save("cf_kv_namespaces_and_keys.json", kv)

    resp = {
        "result": {
            "account_id": account_id,
            "namespace_id": namespace_id,
            "key": key,
            "status": "written",
            "cached": value_bytes <= 65536,
            "cached_value_bytes": row.get("cached_value_bytes"),
        }
    }
    return _finish_ok(resp, 200)

def kv_delete(account_id, namespace_id, key, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0339000" if __import__("os").path.isdir("./environment_mix/0339000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    start = time.time()
