                break

    op_id = "mcop_" + base64.urlsafe_b64encode(os.urandom(18)).decode("utf-8").rstrip("=")
    now = _now()
    op_row = {
        "id": op_id,
        "account_id": account_id if isinstance(account_id, str) else "",
        "tool_name": "kv_delete",
        "status": "received",
        "request_json": {
            "account_id": account_id,
            "namespace_id": namespace_id,
            "key": key,
        },
        "response_json": None,
        "error_message": None,
        "http_status": None,
        "resource_type": "kv",
        "resource_locator": f"{namespace_id}:{key}" if isinstance(namespace_id, str) and isinstance(key, str) else None,
        "duration_ms": None,
        "idempotency_key": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op_row)
    _save("mcp_operations.json", ops)

    def _finish_ok(resp, http_status=200):
        ops2 = _load("mcp_operations.json")
        for r in ops2:
            if r.get("id") == op_id:
                r["status"] = "succeeded"
                r["http_status"] = http_status
                r["response_json"] = resp if isinstance(resp, dict) else {"result": resp}
                r["updated_at"] = _now()
                r["duration_ms"] = int((time.time() - start) * 1000)
                break
        _save("mcp_operations.json", ops2)
        return resp

    def _finish_err(code, msg, http_status=400, **x):
        err = _err(code, msg, **x)
        ops2 = _load("mcp_operations.json")
        for r in ops2:
            if r.get("id") == op_id:
                r["status"] = "failed"
                r["http_status"] = http_status
                r["error_message"] = msg
                r["response_json"] = {"error": err["error"]}
                r["updated_at"] = _now()
                r["duration_ms"] = int((time.time() - start) * 1000)
                break
        _save("mcp_operations.json", ops2)
        return err

    # Validate
    if not isinstance(account_id, str) or not re.match(r"^cfacct_[0-9A-Z]{18,}$", account_id):
        return _finish_err("VALIDATION_ERROR", "account_id is invalid; expected pattern ^cfacct_[0-9A-Z]{18,}$", 400)
    if not isinstance(namespace_id, str) or not namespace_id:
        return _finish_err("VALIDATION_ERROR", "namespace_id is required", 400)
    if not isinstance(key, str) or not key:
        return _finish_err("VALIDATION_ERROR", "key is required", 400)

    if acct is None:
        return _finish_err("NOT_FOUND", "account_id not found", 404)
    if acct.get("status") != "active":
        return _finish_err("UNAUTHORIZED", "account connection is not active", 401)

    kv = _load("cf_kv_namespaces_and_keys.json")
    row = None
    for r in kv:
        if r.get("account_id") == account_id and r.get("namespace_id") == namespace_id and r.get("key") == key:
            row = r
            break

    if row is None:
        return _finish_err("NOT_FOUND", "KV key not found", 404)

    if row.get("status") == "deleted":
        return _finish_err("CONFLICT", "KV key is already deleted", 409)

    # Transition present -> deleted allowed
    row["status"] = "deleted"
    row["cached_value"] = None
    row["cached_value_encoding"] = None
    row["cached_value_bytes"] = None
    row["updated_at"] = _now()
    row["last_seen_at"] = _now()

    _save("cf_kv_namespaces_and_keys.json", kv)

    resp = {
        "result": {
            "account_id": account_id,
            "namespace_id": namespace_id,
            "key": key,
            "status": "deleted",
        }
    }
    return _finish_ok(resp, 200)

def kv_list(account_id, namespace_id, prefix=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0339000" if __import__("os").path.isdir("./environment_mix/0339000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _op_id():
        return "op_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str):
            return None
        # Accept raw integer cursor, or base64("idx:<int>")
        s = cur.strip()
        if s == "":
            return 0
        if re.fullmatch(r"\d+", s):
            return int(s)
        try:
            pad = "=" * ((4 - (len(s) % 4)) % 4)
            decoded = base64.urlsafe_b64decode((s + pad).encode("utf-8")).decode("utf-8")
            if decoded.startswith("idx:") and re.fullmatch(r"idx:\d+", decoded):
                return int(decoded.split(":", 1)[1])
        except Exception:
            return None
        return None

    def _make_cursor(idx):
        raw = f"idx:{idx}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    accounts = _load("cf_accounts.json")
    ops = _load("mcp_operations.json")
    kvs = _load("cf_kv_namespaces_and_keys.json")

    # Create operation row (received)
    op = {
        "id": _op_id(),
        "account_id": account_id if isinstance(account_id, str) else "",
        "tool_name": "kv_list",
        "status": "received",
        "request_json": {
            "account_id": account_id,
            "namespace_id": namespace_id,
            "prefix": prefix,
            "limit": limit,
            "cursor": cursor,
        },
        "response_json": None,
        "error_message": None,
        "http_status": None,
        "resource_type": "kv",
        "resource_locator": f"{namespace_id}" if isinstance(namespace_id, str) else None,
        "duration_ms": None,
        "idempotency_key": None,
        "created_at": _now(),
        "updated_at": _now(),
    }
    ops.append(op)
    _save("mcp_operations.json", ops)

    def _finish_success(resp_obj):
        ops2 = _load("mcp_operations.json")
        for r in reversed(ops2):
            if r.get("id") == op["id"]:
                r["status"] = "succeeded"
                r["updated_at"] = _now()
                r["duration_ms"] = int((time.time() - t0) * 1000)
                r["response_json"] = resp_obj if isinstance(resp_obj, dict) else {"result": resp_obj}
                break
        _save("mcp_operations.json", ops2)
        return resp_obj

    def _finish_fail(err_obj):
        ops2 = _load("mcp_operations.json")
        for r in reversed(ops2):
            if r.get("id") == op["id"]:
                r["status"] = "failed"
                r["updated_at"] = _now()
                r["duration_ms"] = int((time.time() - t0) * 1000)
                r["error_message"] = (err_obj or {}).get("error", {}).get("message")
                r["response_json"] = err_obj
                break
        _save("mcp_operations.json", ops2)
        return err_obj

    # Transition to running
    ops = _load("mcp_operations.json")
    for r in reversed(ops):
        if r.get("id") == op["id"]:
            r["status"] = "running"
            r["updated_at"] = _now()
            break
    _save("mcp_operations.json", ops)

    # Validate inputs
    if not isinstance(account_id, str) or not re.fullmatch(r"^cfacct_[0-9A-Z]{18,}$", account_id):
        return _finish_fail(_err("VALIDATION_ERROR", "account_id is invalid"))
    if not isinstance(namespace_id, str) or namespace_id.strip() == "":
        return _finish_fail(_err("VALIDATION_ERROR", "namespace_id is required"))
    if prefix is not None and (not isinstance(prefix, str)):
        return _finish_fail(_err("VALIDATION_ERROR", "prefix must be a string"))
    if limit is None:
        limit_val = 1000
    else:
        if not isinstance(limit, int):
            return _finish_fail(_err("VALIDATION_ERROR", "limit must be an integer"))
        if limit < 1 or limit > 1000:
            return _finish_fail(_err("VALIDATION_ERROR", "limit out of range", minimum=1, maximum=1000))
        limit_val = limit
    start_idx = _parse_cursor(cursor)
    if start_idx is None:
        return _finish_fail(_err("VALIDATION_ERROR", "cursor is invalid"))

    # Resolve active account
    acct = None
    for a in accounts:
        if a.get("id") == account_id:
            acct = a
            break
    if acct is None:
        return _finish_fail(_err("NOT_FOUND", "account connection not found"))
    if acct.get("status") != "active":
        return _finish_fail(_err("UNAUTHORIZED", "account connection is not active"))

    # List keys from local inventory (namespace_id scoped)
    rows = [r for r in kvs if r.get("account_id") == account_id and r.get("namespace_id") == namespace_id and r.get("status") == "present"]
    if prefix is not None and prefix != "":
        rows = [r for r in rows if isinstance(r.get("key"), str) and r.get("key").startswith(prefix)]

    # Stable sort by key
    rows.sort(key=lambda r: (r.get("key") is None, r.get("key")))

    total = len(rows)
    if start_idx < 0:
        start_idx = 0
    page = rows[start_idx:start_idx + limit_val]
    next_idx = start_idx + len(page)
    has_more = next_idx < total
    next_cursor = _make_cursor(next_idx) if has_more else None

    # Upsert/update last_seen_at for returned keys (kv_list rule)
    now = _now()
    changed = False
    index_by_uk = {}
    for i, r in enumerate(kvs):
        uk = (r.get("account_id"), r.get("namespace_id"), r.get("key"))
        index_by_uk[uk] = i

    for r in page:
        uk = (account_id, namespace_id, r.get("key"))
        i = index_by_uk.get(uk)
        if i is not None:
            # Transition deleted->present allowed; present->present just update timestamps
            if kvs[i].get("status") != "present":
                kvs[i]["status"] = "present"
            kvs[i]["last_seen_at"] = now
            kvs[i]["updated_at"] = now
            changed = True

    if changed:
        _save("cf_kv_namespaces_and_keys.json", kvs)

    resp = {
        "keys": [{"name": r.get("key")} for r in page],
        "result_info": {
            "count": len(page),
            "total": total,
            "cursor": next_cursor,
            "has_more": has_more,
        },
    }
    return _finish_success(resp)

def worker_list(account_id, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0339000" if __import__("os").path.isdir("./environment_mix/0339000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _op_id():
        return "op_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str):
            return None
        s = cur.strip()
        if s == "":
            return 0
        if re.fullmatch(r"\d+", s):
            return int(s)
        try:
            pad = "=" * ((4 - (len(s) % 4)) % 4)
            decoded = base64.urlsafe_b64decode((s + pad).encode("utf-8")).decode("utf-8")
            if decoded.startswith("idx:") and re.fullmatch(r"idx:\d+", decoded):
                return int(decoded.split(":", 1)[1])
        except Exception:
            return None
        return None

    def _make_cursor(idx):
        raw = f"idx:{idx}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    accounts = _load("cf_accounts.json")
    ops = _load("mcp_operations.json")
    workers = _load("cf_workers.json")

    op = {
        "id": _op_id(),
        "account_id": account_id if isinstance(account_id, str) else "",
        "tool_name": "worker_list",
        "status": "received",
        "request_json": {
            "account_id": account_id,
            "status": status,
            "limit": limit,
            "cursor": cursor,
            "sort": sort,
            "order": order,
        },
        "response_json": None,
        "error_message": None,
        "http_status": None,
        "resource_type": "worker",
        "resource_locator": None,
        "duration_ms": None,
        "idempotency_key": None,
        "created_at": _now(),
        "updated_at": _now(),
    }
    ops.append(op)
    _save("mcp_operations.json", ops)

    def _finish_success(resp_obj):
        ops2 = _load("mcp_operations.json")
        for r in reversed(ops2):
            if r.get("id") == op["id"]:
                r["status"] = "succeeded"
                r["updated_at"] = _now()
                r["duration_ms"] = int((time.time() - t0) * 1000)
                r["response_json"] = resp_obj if isinstance(resp_obj, dict) else {"result": resp_obj}
                break
        _save("mcp_operations.json", ops2)
        return resp_obj

    def _finish_fail(err_obj):
        ops2 = _load("mcp_operations.json")
        for r in reversed(ops2):
            if r.get("id") == op["id"]:
                r["status"] = "failed"
                r["updated_at"] = _now()
                r["duration_ms"] = int((time.time() - t0) * 1000)
                r["error_message"] = (err_obj or {}).get("error", {}).get("message")
                r["response_json"] = err_obj
                break
        _save("mcp_operations.json", ops2)
        return err_obj

    # running
    ops = _load("mcp_operations.json")
    for r in reversed(ops):
        if r.get("id") == op["id"]:
            r["status"] = "running"
            r["updated_at"] = _now()
            break
    _save("mcp_operations.json", ops)

    # Validate
    if not isinstance(account_id, str) or not re.fullmatch(r"^cfacct_[0-9A-Z]{18,}$", account_id):
        return _finish_fail(_err("VALIDATION_ERROR", "account_id is invalid"))
    if status is not None and status not in ("active", "deleted"):
        return _finish_fail(_err("VALIDATION_ERROR", "status is invalid", allowed=["active", "deleted"]))
    if limit is None:
        limit_val = 1000
    else:
        if not isinstance(limit, int):
            return _finish_fail(_err("VALIDATION_ERROR", "limit must be an integer"))
        if limit < 1 or limit > 1000:
            return _finish_fail(_err("VALIDATION_ERROR", "limit out of range", minimum=1, maximum=1000))
        limit_val = limit
    if sort is None:
        sort_val = "script_name"
    else:
        if sort not in ("script_name", "last_deployed_at", "updated_at", "created_at"):
            return _finish_fail(_err("VALIDATION_ERROR", "sort is invalid", allowed=["script_name", "last_deployed_at", "updated_at", "created_at"]))
        sort_val = sort
    if order is None:
        order_val = "asc"
    else:
        if order not in ("asc", "desc"):
            return _finish_fail(_err("VALIDATION_ERROR", "order is invalid", allowed=["asc", "desc"]))
        order_val = order
    start_idx = _parse_cursor(cursor)
    if start_idx is None:
        return _finish_fail(_err("VALIDATION_ERROR", "cursor is invalid"))

    acct = None
    for a in accounts:
        if a.get("id") == account_id:
            acct = a
            break
    if acct is None:
        return _finish_fail(_err("NOT_FOUND", "account connection not found"))
    if acct.get("status") != "active":
        return _finish_fail(_err("UNAUTHORIZED", "account connection is not active"))

    rows = [w for w in workers if w.get("account_id") == account_id]
    if status is not None:
        rows = [w for w in rows if w.get("status") == status]

    def _dt_key(v):
        if not isinstance(v, str) or v == "":
            return ""
        return v

    if sort_val in ("created_at", "updated_at", "last_deployed_at"):
        rows.sort(key=lambda r: _dt_key(r.get(sort_val)))
    else:
        rows.sort(key=lambda r: (r.get("script_name") is None, (r.get("script_name") or "")))

    if order_val == "desc":
        rows.reverse()

    total = len(rows)
    if start_idx < 0:
        start_idx = 0
    page = rows[start_idx:start_idx + limit_val]
    next_idx = start_idx + len(page)
    has_more = next_idx < total
    next_cursor = _make_cursor(next_idx) if has_more else None

    resp = {
        "workers": page,
        "result_info": {
            "count": len(page),
            "total": total,
            "cursor": next_cursor,
            "has_more": has_more,
        },
    }
    return _finish_success(resp)

