    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _op_id():
        return "op_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")

    def _new_worker_id():
        return "wkr_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")

    accounts = _load("cf_accounts.json")
    ops = _load("mcp_operations.json")
    workers = _load("cf_workers.json")

    op = {
        "id": _op_id(),
        "account_id": account_id if isinstance(account_id, str) else "",
        "tool_name": "worker_put",
        "status": "received",
        "request_json": {
            "account_id": account_id,
            "script_name": script_name,
            "content": content if (isinstance(content, str) and len(content) <= 4096) else ("<omitted>" if isinstance(content, str) else content),
            "compatibility_date": compatibility_date,
            "compatibility_flags": compatibility_flags,
            "bindings": bindings,
        },
        "response_json": None,
        "error_message": None,
        "http_status": None,
        "resource_type": "worker",
        "resource_locator": script_name if isinstance(script_name, str) else None,
        "duration_ms": None,
        "idempotency_key": None,
        "created_at": _now(),
        "updated_at": _now(),
    }
    ops.append(op)
    _save("mcp_operations.json", ops)

    def _finish_success(resp_obj):
        ops2 = _load("mcp_operations.json")
        for r in reversed(ops2):
            if r.get("id") == op["id"]:
                r["status"] = "succeeded"
                r["updated_at"] = _now()
                r["duration_ms"] = int((time.time() - t0) * 1000)
                r["response_json"] = resp_obj if isinstance(resp_obj, dict) else {"result": resp_obj}
                break
        _save("mcp_operations.json", ops2)
        return resp_obj

    def _finish_fail(err_obj):
        ops2 = _load("mcp_operations.json")
        for r in reversed(ops2):
            if r.get("id") == op["id"]:
                r["status"] = "failed"
                r["updated_at"] = _now()
                r["duration_ms"] = int((time.time() - t0) * 1000)
                r["error_message"] = (err_obj or {}).get("error", {}).get("message")
                r["response_json"] = err_obj
                break
        _save("mcp_operations.json", ops2)
        return err_obj

    # running
    ops = _load("mcp_operations.json")
    for r in reversed(ops):
        if r.get("id") == op["id"]:
            r["status"] = "running"
            r["updated_at"] = _now()
            break
    _save("mcp_operations.json", ops)

    # Validate
    if not isinstance(account_id, str) or not re.fullmatch(r"^cfacct_[0-9A-Z]{18,}$", account_id):
        return _finish_fail(_err("VALIDATION_ERROR", "account_id is invalid"))
    if not isinstance(script_name, str) or script_name.strip() == "":
        return _finish_fail(_err("VALIDATION_ERROR", "script_name is required"))
    if not isinstance(content, str) or content == "":
        return _finish_fail(_err("VALIDATION_ERROR", "content is required"))
    if compatibility_date is not None:
        if not isinstance(compatibility_date, str) or not re.fullmatch(r"^\d{4}-\d{2}-\d{2}$", compatibility_date):
            return _finish_fail(_err("VALIDATION_ERROR", "compatibility_date must be YYYY-MM-DD"))
    if compatibility_flags is None:
        compatibility_flags_val = []
    else:
        if not isinstance(compatibility_flags, list) or any(not isinstance(x, str) for x in compatibility_flags):
            return _finish_fail(_err("VALIDATION_ERROR", "compatibility_flags must be an array of strings"))
        compatibility_flags_val = compatibility_flags
    if bindings is None:
        bindings_val = []
    else:
        if not isinstance(bindings, list) or any(not isinstance(x, dict) for x in bindings):
            return _finish_fail(_err("VALIDATION_ERROR", "bindings must be an array of objects"))
        bindings_val = bindings

    acct = None
    for a in accounts:
        if a.get("id") == account_id:
            acct = a
            break
    if acct is None:
        return _finish_fail(_err("NOT_FOUND", "account connection not found"))
    if acct.get("status") != "active":
        return _finish_fail(_err("UNAUTHORIZED", "account connection is not active"))

    # Upsert by (account_id, script_name) with uniqueness enforcement
    existing_idx = None
    dupes = 0
    for i, w in enumerate(workers):
        if w.get("account_id") == account_id and w.get("script_name") == script_name:
            dupes += 1
            if existing_idx is None:
                existing_idx = i
    if dupes > 1:
        return _finish_fail(_err("CONFLICT", "unique(account_id, script_name) violated"))

    now = _now()
    sha = hashlib.sha256(content.encode("utf-8")).hexdigest()

    if existing_idx is None:
        row = {
            "id": _new_worker_id(),
            "account_id": account_id,
            "script_name": script_name,
            "status": "active",
            "compatibility_date": compatibility_date,
            "compatibility_flags": compatibility_flags_val,
            "bindings": bindings_val,
            "last_content_sha256": sha,
            "last_deployed_at": now,
            "created_at": now,
            "updated_at": now,
        }
        workers.append(row)
        _save("cf_workers.json", workers)
        return _finish_success({"worker": row, "deployed": True})
    else:
        row = workers[existing_idx]
        # If previously deleted, lifecycle transitions do not allow revive; treat as invalid transition.
        if row.get("status") == "deleted":
            return _finish_fail(_err("INVALID_TRANSITION", "cannot update a deleted worker script"))

        row["status"] = "active"
        row["compatibility_date"] = compatibility_date
        row["compatibility_flags"] = compatibility_flags_val
        row["bindings"] = bindings_val
        row["last_content_sha256"] = sha
        row["last_deployed_at"] = now
        row["updated_at"] = now

        workers[existing_idx] = row
        _save("cf_workers.json", workers)
        return _finish_success({"worker": row, "deployed": True})

def analytics_get(account_id, dataset, since, until, granularity=None, metrics=None, dimensions=None, filters=None, limit=None, cursor=None, sort=None, idempotency_key=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0339000" if __import__("os").path.isdir("./environment_mix/0339000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if not isinstance(account_id, str) or not re.match(r"^cfacct_[0-9A-Z]{18,}$", account_id):
        return _err("VALIDATION_ERROR", "account_id is invalid.")
    if dataset not in ("workers", "r2", "kv", "d1"):
        return _err("VALIDATION_ERROR", "dataset is invalid.")
    def _parse_dt(x, name):
        if not isinstance(x, str) or not x:
            return None, _err("VALIDATION_ERROR", f"{name} must be an RFC3339 date-time string.")
        try:
            s = x
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{name} must be an RFC3339 date-time string.")
    dt_since, e1 = _parse_dt(since, "since")
    if e1: return e1
    dt_until, e2 = _parse_dt(until, "until")
    if e2: return e2
    if not (dt_until > dt_since):
        return _err("VALIDATION_ERROR", "until must be greater than since.")
    if granularity is not None and granularity not in ("minute", "hour", "day"):
        return _err("VALIDATION_ERROR", "granularity is invalid.")
    if metrics is not None:
        if not isinstance(metrics, list) or len(metrics) < 1 or any((not isinstance(m, str) or not m.strip()) for m in metrics):
            return _err("VALIDATION_ERROR", "metrics must be a non-empty array of non-empty strings when provided.")
        metrics = [m.strip() for m in metrics]
    else:
        metrics = ["requests"]
    if dimensions is not None:
        if not isinstance(dimensions, list) or any((not isinstance(d, str) or not d.strip()) for d in dimensions):
            return _err("VALIDATION_ERROR", "dimensions must be an array of non-empty strings when provided.")
        dimensions = [d.strip() for d in dimensions]
    else:
        dimensions = []
    if filters is not None:
        if not isinstance(filters, dict):
            return _err("VALIDATION_ERROR", "filters must be an object when provided.")
        for k, v in filters.items():
            if not isinstance(k, str) or not k:
                return _err("VALIDATION_ERROR", "filters keys must be non-empty strings.")
            if not isinstance(v, (str, int, float, bool)):
                return _err("VALIDATION_ERROR", "filters values must be string/number/boolean.")
    else:
        filters = {}
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 1000:
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000 when provided.")
    else:
        limit = 100
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")
        cursor = cursor.strip()
    if sort is not None:
        if not isinstance(sort, str) or not sort.strip():
            return _err("VALIDATION_ERROR", "sort must be a non-empty string when provided.")
        sort = sort.strip()
    if idempotency_key is not None:
        if not isinstance(idempotency_key, str) or not idempotency_key.strip():
            return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided.")
        idempotency_key = idempotency_key.strip()

    accounts = _load("cf_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        return _err("NOT_FOUND", "Account connection not found.")

    ops = _load("mcp_operations.json")
    if acct.get("status") != "active":
        op_id = "op_" + hashlib.sha256(f"{account_id}:analytics_get:{now}:{time.time()}".encode("utf-8")).hexdigest()[:24]
        op = {
            "id": op_id,
            "account_id": account_id,
            "tool_name": "analytics_get",
            "status": "failed",
            "request_json": {
                "account_id": account_id, "dataset": dataset, "since": since, "until": until,
                **({} if granularity is None else {"granularity": granularity}),
                "metrics": metrics,
                **({} if not dimensions else {"dimensions": dimensions}),
                **({} if not filters else {"filters": filters}),
                "limit": limit,
                **({} if cursor is None else {"cursor": cursor}),
                **({} if sort is None else {"sort": sort}),
                **({} if idempotency_key is None else {"idempotency_key": idempotency_key}),
            },
            "response_json": None,
            "error_message": "Account connection is not active.",
            "http_status": 403,
            "resource_type": "analytics",
            "resource_locator": dataset,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "idempotency_key": idempotency_key,
            "created_at": now,
            "updated_at": now,
        }
        ops.append(op)
        _save("mcp_operations.json", ops)
        return _err("UNAUTHORIZED", "Account connection is not active.")

    # Idempotency: return previous response for the same key if present
    if idempotency_key is not None:
        prior = next((o for o in ops if o.get("account_id") == account_id and o.get("idempotency_key") == idempotency_key), None)
        if prior is not None:
            if prior.get("status") == "succeeded":
                return prior.get("response_json") or {}
            return _err("CONFLICT", "Idempotency key already used for a failed operation; cannot reuse.", operation_id=prior.get("id"))

    # Operation row
    op_id = "op_" + hashlib.sha256(f"{account_id}:analytics_get:{now}:{time.time()}".encode("utf-8")).hexdigest()[:24]
    req_json = {
        "account_id": account_id, "dataset": dataset, "since": since, "until": until,
        **({} if granularity is None else {"granularity": granularity}),
        "metrics": metrics,
        **({} if not dimensions else {"dimensions": dimensions}),
        **({} if not filters else {"filters": filters}),
        "limit": limit,
        **({} if cursor is None else {"cursor": cursor}),
        **({} if sort is None else {"sort": sort}),
    }
    if idempotency_key is not None:
        req_json["idempotency_key"] = idempotency_key

    op = {
        "id": op_id,
        "account_id": account_id,
        "tool_name": "analytics_get",
        "status": "received",
        "request_json": req_json,
        "response_json": None,
        "error_message": None,
        "http_status": None,
        "resource_type": "analytics",
        "resource_locator": dataset,
        "duration_ms": None,
        "idempotency_key": idempotency_key,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op)
    _save("mcp_operations.json", ops)
    op["status"] = "running"
    op["updated_at"] = now
    _save("mcp_operations.json", ops)

    # Build "realistic" analytics from local inventories & ops logs.
    # Time buckets according to granularity (default hour).
    gran = granularity or "hour"
    def _floor(dt):
        if gran == "minute":
            return dt.replace(second=0, microsecond=0)
        if gran == "hour":
            return dt.replace(minute=0, second=0, microsecond=0)
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    bucket = _floor(dt_since)
    step = datetime.timedelta(minutes=1 if gran == "minute" else (60 if gran == "hour" else 1440))

    # Cursor decoding: opaque base64 of integer offset
    offset = 0
    if cursor is not None:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                return _err("VALIDATION_ERROR", "cursor is invalid.")
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    # Simple metric sources
    workers = _load("cf_workers.json")
    kvs = _load("cf_kv_namespaces_and_keys.json")
    r2 = _load("cf_r2_buckets_and_objects.json")
    d1 = _load("cf_d1_databases_and_queries.json")

    # Apply filters to inventories (basic equality matches)
    def _match_filters(row, fmap):
        for k, v in fmap.items():
            if row.get(k) != v:
                return False
        return True

    inv = []
    if dataset == "workers":
        inv = [w for w in workers if w.get("account_id") == account_id and w.get("status") == "active" and _match_filters(w, filters)]
    elif dataset == "kv":
        inv = [k for k in kvs if k.get("account_id") == account_id and k.get("status") == "present" and _match_filters(k, filters)]
    elif dataset == "r2":
        inv = [x for x in r2 if x.get("account_id") == account_id and x.get("status") == "active" and _match_filters(x, filters)]
    elif dataset == "d1":
        inv = [x for x in d1 if x.get("account_id") == account_id and _match_filters(x, filters)]

    # Generate rows per bucket window with optional dimensions.
    rows = []
    i = 0
    while bucket < dt_until:
        # One row per time bucket, optionally expanded by dimensions (limited expansion)
        base_dims = {}
        base_dims["timestamp"] = bucket.replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        # Expand a couple common dimensions if requested
        dim_sets = [base_dims]
        if dimensions:
            expanded = []
            for d in dimensions:
                if dataset == "workers" and d in ("script_name",):
                    vals = sorted({w.get("script_name") for w in inv})[:50]
                    if not vals:
                        vals = [None]
                    for ds in dim_sets:
                        for v in vals:
                            nd = dict(ds); nd[d] = v
                            expanded.append(nd)
                    dim_sets = expanded
                elif dataset == "kv" and d in ("namespace_id", "key"):
                    vals = sorted({k.get(d) for k in inv})[:50]
                    if not vals:
                        vals = [None]
                    for ds in dim_sets:
                        for v in vals:
                            nd = dict(ds); nd[d] = v
                            expanded.append(nd)
                    dim_sets = expanded
                elif dataset == "r2" and d in ("bucket_name", "object_key", "entity_type"):
                    vals = sorted({r.get(d) for r in inv})[:50]
                    if not vals:
                        vals = [None]
                    for ds in dim_sets:
                        for v in vals:
                            nd = dict(ds); nd[d] = v
                            expanded.append(nd)
                    dim_sets = expanded
                elif dataset == "d1" and d in ("database_id", "database_name", "status"):
                    vals = sorted({r.get(d) for r in inv})[:50]
                    if not vals:
                        vals = [None]
                    for ds in dim_sets:
                        for v in vals:
                            nd = dict(ds); nd[d] = v
                            expanded.append(nd)
                    dim_sets = expanded
                else:
                    # Unknown dimension: include as None (Cloudflare would error; we accept but return null)
                    for ds in dim_sets:
                        ds[d] = None

        for ds in dim_sets:
            # dataset-specific computed metrics
            out = dict(ds)
            # default computed counts (stable & derived from inventory size + bucket index)
            inv_n = len(inv)
            for m in metrics:
                if m == "requests":
                    out[m] = inv_n * 10 + (i % 10)
                elif m in ("errors", "error_requests"):
                    out[m] = (inv_n + i) % 3
                elif m in ("bytes", "egress_bytes", "ingress_bytes"):
                    out[m] = inv_n * 1024 + (i * 17)
                elif m in ("objects", "keys", "scripts", "databases"):
                    out[m] = inv_n
                elif m in ("latency_ms", "duration_ms"):
                    out[m] = 5 + (i % 20)
                else:
                    # unknown metric: return 0
                    out[m] = 0
            rows.append(out)
        bucket = bucket + step
        i += 1
        # safety
        if len(rows) > 50000:
            break

    # Sorting
    if sort:
        # format field:asc|desc
        parts = sort.split(":")
        fld = parts[0].strip()
        direction = (parts[1].strip().lower() if len(parts) > 1 else "asc")
        rev = direction == "desc"
        def _key(r):
            v = r.get(fld)
            return (v is None, v)
        try:
            rows.sort(key=_key, reverse=rev)
        except Exception:
            pass
    else:
        # default sort by timestamp asc
        rows.sort(key=lambda r: r.get("timestamp") or "")

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "operation_id": op_id,
        "account_id": account_id,
        "dataset": dataset,
        "since": since,
        "until": until,
        "granularity": gran,
        "metrics": metrics,
        "dimensions": dimensions,
        "filters": filters,
        "sort": sort,
        "limit": limit,
        "cursor": cursor,
        "rows": page,
        "result_info": {
            "total": total,
            "count": len(page),
            "has_more": has_more,
            "next_cursor": next_cursor,
        }
    }

    op["status"] = "succeeded"
    # Store response metadata; include rows but could be large—cap stored rows to 2000.
    store_resp = dict(resp)
    if isinstance(store_resp.get("rows"), list) and len(store_resp["rows"]) > 2000:
        store_resp["rows"] = store_resp["rows"][:2000]
        store_resp["result_info"] = dict(store_resp["result_info"])
        store_resp["result_info"]["stored_rows_truncated"] = True
    op["response_json"] = store_resp
    op["http_status"] = 200
    op["duration_ms"] = max(0, int((time.time() - t0) * 1000))
    op["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("mcp_operations.json", ops)
    return resp

def r2_list_buckets(account_id, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0339000" if __import__("os").path.isdir("./environment_mix/0339000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(account_id, str) or not re.match(r"^cfacct_[0-9A-Z]{18,}$", account_id):
        return _err("VALIDATION_ERROR", "account_id is invalid.")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 1000:
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000 when provided.")
    else:
        limit = 100
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")
        cursor = cursor.strip()

    accounts = _load("cf_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        return _err("NOT_FOUND", "Account connection not found.")

    ops = _load("mcp_operations.json")

    # Always log operation; enforce active account
    op_id = "op_" + hashlib.sha256(f"{account_id}:r2_list_buckets:{now}:{time.time()}".encode("utf-8")).hexdigest()[:24]
    req_json = {"account_id": account_id, "limit": limit, **({} if cursor is None else {"cursor": cursor})}
    op = {
        "id": op_id,
        "account_id": account_id,
        "tool_name": "r2_list_buckets",
        "status": "received",
        "request_json": req_json,
        "response_json": None,
        "error_message": None,
        "http_status": None,
        "resource_type": "r2",
        "resource_locator": None,
        "duration_ms": None,
        "idempotency_key": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op)
    _save("mcp_operations.json", ops)
    op["status"] = "running"
    op["updated_at"] = now
    _save("mcp_operations.json", ops)

    if acct.get("status") != "active":
        op["status"] = "failed"
        op["error_message"] = "Account connection is not active."
        op["http_status"] = 403
        op["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        op["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("mcp_operations.json", ops)
        return _err("UNAUTHORIZED", "Account connection is not active.")

    # Cursor decode -> offset
    offset = 0
    if cursor is not None:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                raise ValueError()
        except Exception:
            op["status"] = "failed"
            op["error_message"] = "Invalid cursor."
            op["http_status"] = 400
            op["duration_ms"] = max(0, int((time.time() - t0) * 1000))
            op["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            _save("mcp_operations.json", ops)
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    r2rows = _load("cf_r2_buckets_and_objects.json")

    # Business rule says list should upsert bucket rows, but offline we only have local store to reflect.
    # Ensure all bucket rows for this account have correct shape and are active unless deleted.
    changed = False
    for r in r2rows:
        if r.get("account_id") == account_id and r.get("entity_type") == "bucket":
            if r.get("object_key") is not None:
                r["object_key"] = None
                changed = True
            if r.get("status") not in ("active", "deleted"):
                r["status"] = "active"
                changed = True
            if not r.get("updated_at"):
                r["updated_at"] = now
                changed = True
    if changed:
        _save("cf_r2_buckets_and_objects.json", r2rows)

    buckets = [r for r in r2rows if r.get("account_id") == account_id and r.get("entity_type") == "bucket"]
    # Sort by bucket_name
    buckets.sort(key=lambda x: (x.get("bucket_name") or ""))

    total = len(buckets)
    page = buckets[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    # Response format
    resp = {
        "operation_id": op_id,
        "account_id": account_id,
        "buckets": [
            {
                "bucket_name": b.get("bucket_name"),
                "status": b.get("status"),
                "created_at": b.get("created_at"),
                "updated_at": b.get("updated_at"),
            }
            for b in page
        ],
        "result_info": {
            "total": total,
            "count": len(page),
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "limit": limit,
        "cursor": cursor,
    }

    op["status"] = "succeeded"
    op["response_json"] = resp
    op["http_status"] = 200
    op["duration_ms"] = max(0, int((time.time() - t0) * 1000))
    op["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("mcp_operations.json", ops)
    return resp

def r2_list_objects(account_id, bucket_name, prefix=None, delimiter=None, start_after=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0339000" if __import__("os").path.isdir("./environment_mix/0339000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now(): return datetime.datetime.now(datetime.timezone.utc).isoformat()
    def _ms(): return max(0, int((time.time() - t0) * 1000))
    def _new_id(prefix_):
        return f"{prefix_}_{base64.urlsafe_b64encode(os.urandom(18)).decode('utf-8').rstrip('=')}"

    def _encode_cursor(offset):
        return base64.urlsafe_b64encode(json.dumps({"v": 1, "o": int(offset)}).encode("utf-8")).decode("utf-8").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur.strip():
            return None, "cursor must be a non-empty string"
        pad = "=" * (-len(cur) % 4)
        try:
            obj = json.loads(base64.urlsafe_b64decode((cur + pad).encode("utf-8")).decode("utf-8"))
        except Exception:
            return None, "invalid cursor"
        if not isinstance(obj, dict) or obj.get("v") != 1:
            return None, "invalid cursor"
        try:
            off = int(obj.get("o"))
        except Exception:
            return None, "invalid cursor"
        if off < 0:
            return None, "invalid cursor"
        return off, None

    # Build request capture
    req = {"account_id": account_id, "bucket_name": bucket_name}
    if prefix is not None: req["prefix"] = prefix
    if delimiter is not None: req["delimiter"] = delimiter
    if start_after is not None: req["start_after"] = start_after
    if limit is not None: req["limit"] = limit
    if cursor is not None: req["cursor"] = cursor

    # Create op row (received)
    op_id = _new_id("mcpo")
    created_at = _now()
    ops = _load("mcp_operations.json")
    ops.append({
        "id": op_id,
        "account_id": account_id if isinstance(account_id, str) else "",
        "tool_name": "r2_list_objects",
        "status": "received",
        "request_json": req,
        "response_json": None,
        "error_message": None,
        "http_status": None,
        "resource_type": "r2",
        "resource_locator": f"{bucket_name}" if isinstance(bucket_name, str) else None,
        "duration_ms": None,
        "idempotency_key": None,
        "created_at": created_at,
        "updated_at": created_at,
    })
    _save("mcp_operations.json", ops)

    def _set_op(status, response_json=None, error_message=None, http_status=None):
        ops2 = _load("mcp_operations.json")
        for r in ops2:
            if r.get("id") == op_id:
                r["status"] = status
                r["updated_at"] = _now()
                r["duration_ms"] = _ms()
                r["response_json"] = response_json
                r["error_message"] = error_message
                r["http_status"] = http_status
                break
        _save("mcp_operations.json", ops2)

    # Transition to running
    _set_op("running", response_json={"stage": "running"})

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^cfacct_[0-9A-Z]{18,}$", account_id):
        _set_op("failed", response_json={"error": {"code": "VALIDATION_ERROR", "message": "account_id is invalid"}}, error_message="account_id is invalid", http_status=400)
        return _err("VALIDATION_ERROR", "account_id is invalid")
    if not isinstance(bucket_name, str) or len(bucket_name) < 1:
        _set_op("failed", response_json={"error": {"code": "VALIDATION_ERROR", "message": "bucket_name is invalid"}}, error_message="bucket_name is invalid", http_status=400)
        return _err("VALIDATION_ERROR", "bucket_name is invalid")
    if prefix is not None and (not isinstance(prefix, str)):
        _set_op("failed", response_json={"error": {"code": "VALIDATION_ERROR", "message": "prefix must be a string"}}, error_message="prefix must be a string", http_status=400)
        return _err("VALIDATION_ERROR", "prefix must be a string")
    if delimiter is not None:
        # schema says string; audit showed some callers send integers: accept and coerce to str
        if isinstance(delimiter, int):
            delimiter = str(delimiter)
        if not isinstance(delimiter, str) or len(delimiter) < 1:
            _set_op("failed", response_json={"error": {"code": "VALIDATION_ERROR", "message": "delimiter must be a non-empty string"}}, error_message="delimiter must be a non-empty string", http_status=400)
            return _err("VALIDATION_ERROR", "delimiter must be a non-empty string")
    if start_after is not None and (not isinstance(start_after, str) or len(start_after) < 1):
        _set_op("failed", response_json={"error": {"code": "VALIDATION_ERROR", "message": "start_after must be a non-empty string"}}, error_message="start_after must be a non-empty string", http_status=400)
        return _err("VALIDATION_ERROR", "start_after must be a non-empty string")
    if limit is None:
        limit = 1000
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        _set_op("failed", response_json={"error": {"code": "VALIDATION_ERROR", "message": "limit must be an integer between 1 and 1000"}}, error_message="limit must be an integer between 1 and 1000", http_status=400)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000")

    offset, cerr = _decode_cursor(cursor)
    if cerr:
        _set_op("failed", response_json={"error": {"code": "VALIDATION_ERROR", "message": cerr}}, error_message=cerr, http_status=400)
        return _err("VALIDATION_ERROR", cerr)

    # Resolve active account context (must match requested id)
    accounts = _load("cf_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        _set_op("failed", response_json={"error": {"code": "NOT_FOUND", "message": "Account not found"}}, error_message="Account not found", http_status=404)
        return _err("NOT_FOUND", "Account not found")
    if acct.get("status") != "active":
        _set_op("failed", response_json={"error": {"code": "UNAUTHORIZED", "message": "Account is not active"}}, error_message="Account is not active", http_status=401)
        return _err("UNAUTHORIZED", "Account is not active")

    # Find bucket row; accept active bucket inventory row existing, and do not require prior r2_list_buckets.
    r2 = _load("cf_r2_buckets_and_objects.json")
    bucket_row = None
    for row in r2:
        if row.get("account_id") == account_id and row.get("bucket_name") == bucket_name and row.get("entity_type") == "bucket" and row.get("object_key") is None:
            bucket_row = row
            break
    if not bucket_row or bucket_row.get("status") != "active":
        _set_op("failed", response_json={"error": {"code": "NOT_FOUND", "message": "Bucket not found"}}, error_message="Bucket not found", http_status=404)
        return _err("NOT_FOUND", "Bucket not found")

    # List objects under bucket
    objs = []
    for row in r2:
        if row.get("account_id") != account_id: continue
        if row.get("bucket_name") != bucket_name: continue
        if row.get("entity_type") != "object": continue
        if row.get("status") != "active": continue
        key = row.get("object_key")
        if not isinstance(key, str): continue
        if prefix is not None and not key.startswith(prefix): continue
        objs.append(row)

    # Sort by key lexicographically
    objs.sort(key=lambda r: r.get("object_key", ""))

    # Apply start_after and cursor offset (cursor is absolute offset into filtered list)
    if start_after is not None:
        objs = [r for r in objs if r.get("object_key", "") > start_after]

    total = len(objs)
    if offset > total:
        # treat as end of listing rather than error
        page = []
        next_cursor = None
    else:
        page = objs[offset:offset + limit]
        next_off = offset + len(page)
        next_cursor = _encode_cursor(next_off) if next_off < total else None

    # Delimiter handling: simulate "common prefixes" and filter returned objects accordingly
    common_prefixes = []
    if delimiter is not None:
        seen = set()
        filtered = []
        for r in page:
            k = r.get("object_key", "")
            base = prefix or ""
            rest = k[len(base):] if k.startswith(base) else k
            idx = rest.find(delimiter)
