                return _err("CONFLICT", "Object exists; if_none_match='*' requires non-existence.")
        else:
            if obj_row and obj_row.get("status") == "active" and obj_row.get("etag") == if_none_match:
                _set_op("failed", response_json={"error": {"code": "CONFLICT", "message": "Object ETag matches if_none_match precondition."}}, error_message="Object ETag matches if_none_match precondition.", http_status=409)
                return _err("CONFLICT", "Object ETag matches if_none_match precondition.")

    # Upsert object row
    now = _now()
    etag = hashlib.md5(body_bytes).hexdigest()  # deterministic enough for local store

    # cache only when <= 262144
    cached_b64 = None
    cached_bytes = None
    if len(body_bytes) <= 262144:
        cached_b64 = base64.b64encode(body_bytes).decode("utf-8")
        cached_bytes = len(body_bytes)

    if obj_row is None:
        obj_row = {
            "id": _new_id("cfr2o"),
            "account_id": account_id,
            "bucket_name": bucket_name,
            "object_key": object_key,
            "entity_type": "object",
            "status": "active",
            "etag": None,
            "size_bytes": None,
            "content_type": None,
            "last_modified_at": None,
            "cached_body_base64": None,
            "cached_body_bytes": None,
            "created_at": now,
            "updated_at": now,
        }
        r2.append(obj_row)
    else:
        # If was deleted, revive allowed? lifecycle says deleted -> [] for r2, but this is an object overwrite; treat as creating anew by setting active if deleted is not allowed.
        # Enforce lifecycle: cannot transition deleted->active.
        if obj_row.get("status") == "deleted":
            _set_op("failed", response_json={"error": {"code": "INVALID_TRANSITION", "message": "Cannot overwrite a deleted object record; delete/create bucket inventory first."}}, error_message="Cannot overwrite a deleted object record; delete/create bucket inventory first.", http_status=409)
            return _err("INVALID_TRANSITION", "Cannot overwrite a deleted object record; delete/create bucket inventory first.")
        obj_row["updated_at"] = now

    obj_row["status"] = "active"
    obj_row["etag"] = etag
    obj_row["size_bytes"] = len(body_bytes)
    if content_type is not None:
        obj_row["content_type"] = content_type
    elif obj_row.get("content_type") is None:
        obj_row["content_type"] = "application/octet-stream"
    obj_row["last_modified_at"] = now
    obj_row["cached_body_base64"] = cached_b64
    obj_row["cached_body_bytes"] = cached_bytes

    _save("cf_r2_buckets_and_objects.json", r2)

    result = {
        "bucket_name": bucket_name,
        "object_key": object_key,
        "etag": etag,
        "size_bytes": len(body_bytes),
        "content_type": obj_row.get("content_type"),
        "last_modified_at": now,
        "body_cached": True if cached_b64 is not None else False,
    }
    _set_op("succeeded", response_json={"result": result}, http_status=200)
    return result

