def d1_list_databases(account_id, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, re, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0339000" if __import__("os").path.isdir("./environment_mix/0339000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^cfacct_[0-9A-Z]{20,}$", account_id):
        return _err("VALIDATION_ERROR", "Malformed account_id.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000.")
    if cursor is not None and (not isinstance(cursor, str) or len(cursor) < 1):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")
    if sort is None:
        sort = "name_asc"
    if sort not in ("name_asc", "name_desc", "created_at_asc", "created_at_desc"):
        return _err("VALIDATION_ERROR", "sort must be one of: name_asc, name_desc, created_at_asc, created_at_desc.")

    accounts = _load("cf_accounts.json")
    d1 = _load("cf_d1_databases_and_queries.json")
    ops = _load("mcp_operations.json")

    acct = next((a for a in accounts if a.get("id") == account_id), None)

    op_id = "op_" + uuid.uuid4().hex
    op = {
        "id": op_id,
        "account_id": account_id,
        "tool_name": "d1_list_databases",
        "status": "received",
        "request_json": {
            "account_id": account_id,
            "limit": limit,
            **({"cursor": cursor} if cursor is not None else {}),
            "sort": sort,
        },
        "response_json": None,
        "error_message": None,
        "http_status": None,
        "resource_type": "d1",
        "resource_locator": None,
        "duration_ms": None,
        "idempotency_key": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op)
    _save("mcp_operations.json", ops)

    def _finalize(success, response_json=None, error_code=None, error_message=None, http_status=None):
        end = time.time()
        dur_ms = int(round((end - t0) * 1000))
        ops2 = _load("mcp_operations.json")
        row = next((o for o in ops2 if o.get("id") == op_id), None)
        if row is None:
            return _err("CONFLICT", "Operation log missing; cannot finalize.")
        if row.get("status") == "received":
            row["status"] = "running"
            row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row["status"] = "succeeded" if success else "failed"
        row["response_json"] = response_json
        row["error_message"] = error_message
        row["http_status"] = http_status
        row["duration_ms"] = dur_ms
        row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("mcp_operations.json", ops2)
        if success:
            return response_json
        return _err(error_code or "CONFLICT", error_message or "Request failed.")

    if acct is None:
        return _finalize(False, response_json=None, error_code="NOT_FOUND", error_message="Account not found.", http_status=404)
    if acct.get("status") != "active":
        return _finalize(False, response_json=None, error_code="UNAUTHORIZED", error_message="Account is not active.", http_status=403)

    # Cursor: base64url encoded integer offset
    offset = 0
    if cursor is not None:
        try:
            padded = cursor + "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            offset = int(raw)
            if offset < 0:
                return _finalize(False, response_json=None, error_code="VALIDATION_ERROR", error_message="Invalid cursor.", http_status=400)
        except Exception:
            return _finalize(False, response_json=None, error_code="VALIDATION_ERROR", error_message="Invalid cursor.", http_status=400)

    rows = [r for r in d1 if r.get("account_id") == account_id and r.get("entity_type") == "database" and r.get("status") != "deleted"]

    def _safe_dt(s):
        if not isinstance(s, str):
            return ""
        return s

    if sort == "name_asc":
        rows.sort(key=lambda r: (r.get("database_name") or "", r.get("database_id") or "", r.get("id") or ""))
    elif sort == "name_desc":
        rows.sort(key=lambda r: (r.get("database_name") or "", r.get("database_id") or "", r.get("id") or ""), reverse=True)
    elif sort == "created_at_asc":
        rows.sort(key=lambda r: (_safe_dt(r.get("created_at")), r.get("database_id") or "", r.get("id") or ""))
    elif sort == "created_at_desc":
        rows.sort(key=lambda r: (_safe_dt(r.get("created_at")), r.get("database_id") or "", r.get("id") or ""), reverse=True)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    result = {
        "databases": [
            {
                "id": r.get("id"),
                "account_id": r.get("account_id"),
                "database_id": r.get("database_id"),
                "database_name": r.get("database_name"),
                "status": r.get("status"),
                "created_at": r.get("created_at"),
                "updated_at": r.get("updated_at"),
            } for r in page
        ],
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }
    return _finalize(True, response_json=result, http_status=200)

