def d1_query(account_id, database_id, sql_text, parameters=None, limit=None, cursor=None, idempotency_key=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0339000" if __import__("os").path.isdir("./environment_mix/0339000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now_dt(): return datetime.datetime.now(datetime.timezone.utc)
    def _now(): return _now_dt().isoformat()
    def _ms(): return max(0, int((time.time() - t0) * 1000))
    def _new_id(prefix_):
        return f"{prefix_}_{base64.urlsafe_b64encode(os.urandom(18)).decode('utf-8').rstrip('=')}"

    def _encode_cursor(offset):
        return base64.urlsafe_b64encode(json.dumps({"v": 1, "o": int(offset)}).encode("utf-8")).decode("utf-8").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return 0, None
        if not isinstance(cur, str) or not cur.strip():
            return None, "cursor must be a non-empty string"
        pad = "=" * (-len(cur) % 4)
        try:
            obj = json.loads(base64.urlsafe_b64decode((cur + pad).encode("utf-8")).decode("utf-8"))
        except Exception:
            return None, "invalid cursor"
        if not isinstance(obj, dict) or obj.get("v") != 1:
            return None, "invalid cursor"
        try:
            off = int(obj.get("o"))
        except Exception:
            return None, "invalid cursor"
        if off < 0:
            return None, "invalid cursor"
        return off, None

    req = {"account_id": account_id, "database_id": database_id, "sql_text": sql_text}
    if parameters is not None: req["parameters"] = parameters
    if limit is not None: req["limit"] = limit
    if cursor is not None: req["cursor"] = cursor
    if idempotency_key is not None: req["idempotency_key"] = idempotency_key

    ops = _load("mcp_operations.json")
    # Idempotency (same as other tools): return original succeeded result
    if idempotency_key is not None:
        for op in ops:
            if op.get("account_id") == account_id and op.get("idempotency_key") == idempotency_key and op.get("tool_name") == "d1_query":
                if op.get("status") == "succeeded" and isinstance(op.get("response_json"), dict) and "result" in op["response_json"]:
                    return op["response_json"]["result"]
                if op.get("status") in ("received", "running"):
                    return _err("CONFLICT", "Operation with this idempotency_key is already in progress")
                return _err("CONFLICT", "idempotency_key already used for a previous operation")
        for op in ops:
            if op.get("account_id") == account_id and op.get("idempotency_key") == idempotency_key:
                return _err("CONFLICT", "idempotency_key already used for a previous operation")

    op_id = _new_id("mcpo")
    created_at = _now()
    ops.append({
        "id": op_id,
        "account_id": account_id if isinstance(account_id, str) else "",
        "tool_name": "d1_query",
        "status": "received",
        "request_json": req,
        "response_json": None,
        "error_message": None,
        "http_status": None,
        "resource_type": "d1",
        "resource_locator": database_id if isinstance(database_id, str) else None,
        "duration_ms": None,
        "idempotency_key": idempotency_key,
        "created_at": created_at,
        "updated_at": created_at,
    })
    _save("mcp_operations.json", ops)

    def _set_op(status, response_json=None, error_message=None, http_status=None):
        ops2 = _load("mcp_operations.json")
        for r in ops2:
            if r.get("id") == op_id:
                r["status"] = status
                r["updated_at"] = _now()
                r["duration_ms"] = _ms()
                r["response_json"] = response_json
                r["error_message"] = error_message
                r["http_status"] = http_status
                break
        _save("mcp_operations.json", ops2)

    _set_op("running", response_json={"stage": "running"})

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^cfacct_[0-9A-Z]{18,}$", account_id):
        _set_op("failed", response_json={"error": {"code": "VALIDATION_ERROR", "message": "account_id is invalid"}}, error_message="account_id is invalid", http_status=400)
        return _err("VALIDATION_ERROR", "account_id is invalid")
    if not isinstance(database_id, str) or len(database_id) < 1:
        _set_op("failed", response_json={"error": {"code": "VALIDATION_ERROR", "message": "database_id is invalid"}}, error_message="database_id is invalid", http_status=400)
        return _err("VALIDATION_ERROR", "database_id is invalid")
    if not isinstance(sql_text, str) or len(sql_text) < 1:
        _set_op("failed", response_json={"error": {"code": "VALIDATION_ERROR", "message": "sql_text is invalid"}}, error_message="sql_text is invalid", http_status=400)
        return _err("VALIDATION_ERROR", "sql_text is invalid")
    if parameters is not None and not isinstance(parameters, dict):
        _set_op("failed", response_json={"error": {"code": "VALIDATION_ERROR", "message": "parameters must be an object"}}, error_message="parameters must be an object", http_status=400)
        return _err("VALIDATION_ERROR", "parameters must be an object")
    if limit is None:
        limit = 10000
    if not isinstance(limit, int) or limit < 1 or limit > 10000:
        _set_op("failed", response_json={"error": {"code": "VALIDATION_ERROR", "message": "limit must be an integer between 1 and 10000"}}, error_message="limit must be an integer between 1 and 10000", http_status=400)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 10000")
    offset, cerr = _decode_cursor(cursor)
    if cerr:
        _set_op("failed", response_json={"error": {"code": "VALIDATION_ERROR", "message": cerr}}, error_message=cerr, http_status=400)
        return _err("VALIDATION_ERROR", cerr)

    # Resolve active account
    accounts = _load("cf_accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        _set_op("failed", response_json={"error": {"code": "NOT_FOUND", "message": "Account not found"}}, error_message="Account not found", http_status=404)
        return _err("NOT_FOUND", "Account not found")
    if acct.get("status") != "active":
        _set_op("failed", response_json={"error": {"code": "UNAUTHORIZED", "message": "Account is not active"}}, error_message="Account is not active", http_status=401)
        return _err("UNAUTHORIZED", "Account is not active")

    d1 = _load("cf_d1_databases_and_queries.json")
    db_row = None
    for row in d1:
        if row.get("account_id") == account_id and row.get("entity_type") == "database" and row.get("database_id") == database_id and row.get("status") == "active":
            db_row = row
            break
    if not db_row:
        _set_op("failed", response_json={"error": {"code": "NOT_FOUND", "message": "Database not found"}}, error_message="Database not found", http_status=404)
        return _err("NOT_FOUND", "Database not found")

    # Create query_execution row with lifecycle queued->running->succeeded|failed
    qe_id = _new_id("cfd1q")
    now = _now()
    qe = {
        "id": qe_id,
        "account_id": account_id,
        "entity_type": "query_execution",
        "database_id": database_id,
        "database_name": db_row.get("database_name"),
        "status": "queued",
        "sql_text": sql_text,
        "parameters_json": parameters if parameters is not None else {},
        "result_rows_json": None,
        "result_truncated": False,
        "error_message": None,
        "duration_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    d1.append(qe)
    _save("cf_d1_databases_and_queries.json", d1)

    # Move to running
    qe["status"] = "running"
    qe["updated_at"] = _now()
    _save("cf_d1_databases_and_queries.json", d1)

    # Offline execution simulation: store deterministic pseudo-results for SELECT-like queries; otherwise empty.
    start_exec = time.time()
    sql_upper = sql_text.strip().upper()

    try:
        rows = []
        if sql_upper.startswith("SELECT") or " RETURNING " in sql_upper:
            # Deterministic pseudo rows: based on sql_text hash and parameters
            h = hashlib.sha256((sql_text + json.dumps(qe["parameters_json"], sort_keys=True)).encode("utf-8")).hexdigest()
            # generate up to 50 sample rows
            sample_n = 50
            for i in range(sample_n):
                rows.append({"_row": i, "_hash": h[:16], "database_id": database_id})
        else:
            # DDL/DML: return empty rows and a changes count
            rows = []
        # Apply pagination
        total = len(rows)
        page = rows[offset:offset + limit] if offset <= total else []
        next_off = offset + len(page)
        next_cursor = _encode_cursor(next_off) if next_off < total else None

        # Store result_rows_json only up to limit (server-defined cap)
        STORE_CAP = 200
        stored = page[:STORE_CAP]
        truncated = len(page) > STORE_CAP

        qe["status"] = "succeeded"
        qe["result_rows_json"] = stored
        qe["result_truncated"] = truncated
        qe["duration_ms"] = max(0, int((time.time() - start_exec) * 1000))
        qe["updated_at"] = _now()
        _save("cf_d1_databases_and_queries.json", d1)

        result = {
            "database_id": database_id,
            "query_execution_id": qe_id,
            "rows": page,
            "row_count": len(page),
            "cursor": next_cursor,
            "has_more": bool(next_cursor),
            "result_truncated": truncated,
        }
        _set_op("succeeded", response_json={"result": result}, http_status=200)
        return result
    except Exception as e:
        # mark failed
        qe["status"] = "failed"
        qe["error_message"] = str(e)
        qe["duration_ms"] = max(0, int((time.time() - start_exec) * 1000))
        qe["updated_at"] = _now()
        _save("cf_d1_databases_and_queries.json", d1)
        _set_op("failed", response_json={"error": {"code": "CONFLICT", "message": "Query execution failed"}}, error_message=str(e), http_status=409)
        return _err("CONFLICT", "Query execution failed", detail=str(e))

def cf_account_patch(id, display_name=None, status=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0339000" if __import__("os").path.isdir("./environment_mix/0339000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _ms():
        return max(0, int((time.time() - t0) * 1000))

    def _new_id(prefix_):
        return f"{prefix_}_{base64.urlsafe_b64encode(os.urandom(18)).decode('utf-8').rstrip('=')}"

    # Validate inputs
    if not isinstance(id, str) or not re.match(r"^cfacct_[0-9A-Z]{18,}$", id):
        ops = _load("mcp_operations.json")
        ops.append({
            "id": _new_id("mcpo"),
            "account_id": id if isinstance(id, str) else "",
            "tool_name": "cf_account_patch",
            "status": "failed",
            "request_json": {"id": id, **({} if display_name is None else {"display_name": display_name}), **({} if status is None else {"status": status})},
            "response_json": None,
            "error_message": "id is missing/invalid",
            "http_status": 400,
            "resource_type": "system",
            "resource_locator": f"cfacct:{id}" if isinstance(id, str) else None,
            "duration_ms": _ms(),
            "idempotency_key": None,
            "created_at": now,
            "updated_at": now,
        })
        _save("mcp_operations.json", ops)
        return _err("VALIDATION_ERROR", "id is missing/invalid")
    if display_name is not None and (not isinstance(display_name, str) or not (1 <= len(display_name) <= 200)):
        return _err("VALIDATION_ERROR", "display_name must be 1..200 chars")
    if status is not None and status not in ("active", "disabled", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled, revoked")

    accounts = _load("cf_accounts.json")
    workers = _load("cf_workers.json")
    kv = _load("cf_kv_namespaces_and_keys.json")
    r2 = _load("cf_r2_buckets_and_objects.json")
    d1 = _load("cf_d1_databases_and_queries.json")
    ops = _load("mcp_operations.json")

    op_id = _new_id("mcpo")
    op = {
        "id": op_id,
        "account_id": id,
        "tool_name": "cf_account_patch",
        "status": "received",
        "request_json": {"id": id, **({} if display_name is None else {"display_name": display_name}), **({} if status is None else {"status": status})},
        "response_json": None,
        "error_message": None,
        "http_status": None,
        "resource_type": "system",
        "resource_locator": f"cfacct:{id}",
        "duration_ms": None,
        "idempotency_key": None,
        "created_at": now,
        "updated_at": now,
    }
    ops.append(op)
    _save("mcp_operations.json", ops)

    def _set_op(status_, response=None, error_message=None, http_status=None):
        ops2 = _load("mcp_operations.json")
        for o in ops2:
            if o.get("id") == op_id:
                o["status"] = status_
                if response is not None:
                    o["response_json"] = response
                if error_message is not None:
                    o["error_message"] = error_message
                if http_status is not None:
                    o["http_status"] = http_status
                o["duration_ms"] = _ms() if status_ in ("succeeded", "failed") else o.get("duration_ms")
                o["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
                break
        _save("mcp_operations.json", ops2)

    _set_op("running")

    acct = next((a for a in accounts if a.get("id") == id), None)
    if not acct:
        _set_op("failed", error_message="Account not found.", http_status=404)
        return _err("NOT_FOUND", "Account not found.")

    # Apply updates with lifecycle transition validation
    changed = False
    if display_name is not None and display_name != acct.get("display_name"):
        acct["display_name"] = display_name
        changed = True

    if status is not None and status != acct.get("status"):
        cur = acct.get("status")
        transitions = {"active": ["disabled", "revoked"], "disabled": ["active", "revoked"], "revoked": []}
        if cur not in transitions or status not in transitions[cur]:
            _set_op("failed", error_message="Invalid status transition.", http_status=409)
            return _err("INVALID_TRANSITION", f"Invalid status transition from {cur} to {status}.")
        # FK rule: revoking is not allowed while dependent rows exist -> refuse
        if status == "revoked":
            deps = False
            for coll in (workers, kv, r2, d1):
                if any(x.get("account_id") == id for x in coll):
                    deps = True
                    break
            if deps:
                _set_op("failed", error_message="Cannot revoke account while dependent inventory exists.", http_status=409)
                return _err("CONFLICT", "Cannot revoke account while dependent inventory rows exist; keep account for auditability.")
        acct["status"] = status
        changed = True

    if not changed:
        # No success without effect: if patch matched but changed nothing, still return current record? Real patch often returns same.
        # However contract says no success without effect for mutations that matched no row. This matched a row. Return as succeeded.
        pass

    acct["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    _save("cf_accounts.json", accounts)

    resp = acct
    _set_op("succeeded", response=resp, http_status=200)
    return resp

def d1_get_databases(account_id, database_id=None, database_name=None, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0339000" if __import__("os").path.isdir("./environment_mix/0339000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            # Not expected in this store; treat as invalid sentinel
            return None
        if not isinstance(s, str):
            return None
        try:
            # Support "Z"
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _b64url_json(obj):
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _b64url_load(s):
        if not isinstance(s, str) or not s:
            return None
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    start = time.time()
    op_file = "mcp_operations.json"
    ops = _load(op_file)

    # Validate inputs first
    if not isinstance(account_id, str) or not re.match(r"^cfacct_[0-9A-Z]{18,}$", account_id):
        return _err("VALIDATION_ERROR", "account_id is invalid; expected pattern ^cfacct_[0-9A-Z]{18,}$")
    if database_id is not None and not isinstance(database_id, str):
        return _err("VALIDATION_ERROR", "database_id must be a string")
    if database_name is not None and not isinstance(database_name, str):
        return _err("VALIDATION_ERROR", "database_name must be a string")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of: active, deleted")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sort is None:
        sort = "updated_at"
    if not isinstance(sort, str) or sort not in ("database_name", "database_id", "updated_at", "created_at"):
        return _err("VALIDATION_ERROR", "sort must be one of: database_name, database_id, updated_at, created_at")
    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc")

    # Prepare operation log row (received)
    def _new_op_id(existing):
        # mcpop_ + 20 base32-ish uppercase chars derived from time and counter
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        t = int(time.time() * 1000)
        x = t
        out = []
        for _ in range(12):
            out.append(alphabet[x % 32])
            x //= 32
        # add a counter component to reduce collisions
        c = len(existing) % (32 ** 6)
        for _ in range(6):
            out.append(alphabet[c % 32])
            c //= 32
        out.append(alphabet[(t // 7) % 32])
        out.append(alphabet[(t // 13) % 32])
        return "mcpop_" + "".join(out)

    req_json = {
        "account_id": account_id,
        **({} if database_id is None else {"database_id": database_id}),
        **({} if database_name is None else {"database_name": database_name}),
        **({} if status is None else {"status": status}),
        "limit": limit,
        **({} if cursor is None else {"cursor": cursor}),
        "sort": sort,
        "order": order,
    }

    op_row = {
        "id": _new_op_id(ops),
        "account_id": account_id,
        "tool_name": "d1_list_databases",  # best matching vendor operation name in schema
        "status": "received",
        "request_json": req_json,
        "response_json": None,
        "error_message": None,
        "http_status": None,
        "resource_type": "d1",
        "resource_locator": None,
        "duration_ms": None,
        "idempotency_key": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    ops.append(op_row)
    _save(op_file, ops)

    def _finalize(status_str, resp_obj=None, err_msg=None, http_status=None):
        # reload to ensure we update the same row even if store changed
        ops2 = _load(op_file)
        for r in reversed(ops2):
            if r.get("id") == op_row["id"]:
                r["status"] = status_str
                r["updated_at"] = _now_iso()
                r["duration_ms"] = int((time.time() - start) * 1000)
                r["http_status"] = http_status
                if status_str == "failed":
                    r["error_message"] = err_msg or "operation failed"
                    # keep response_json minimal
                    r["response_json"] = resp_obj if isinstance(resp_obj, dict) else {"error": True}
                else:
                    r["error_message"] = None
                    r["response_json"] = resp_obj if isinstance(resp_obj, dict) else {}
                break
        _save(op_file, ops2)

    # AUTH (ambient): tool must execute within scope of exactly one active account row matching account_id
    accounts = _load("cf_accounts.json")
    acct = None
    for a in accounts:
        if a.get("id") == account_id:
            acct = a
            break
    if acct is None:
        e = _err("UNAUTHORIZED", "Caller cannot use the specified account connection.")
        _finalize("failed", resp_obj={"error": e["error"]}, err_msg=e["error"]["message"], http_status=401)
        return e
    if acct.get("status") != "active":
        e = _err("UNAUTHORIZED", "Account connection is not active.", account_status=acct.get("status"))
        _finalize("failed", resp_obj={"error": e["error"]}, err_msg=e["error"]["message"], http_status=401)
        return e

    # Transition to running
    ops3 = _load(op_file)
    for r in reversed(ops3):
        if r.get("id") == op_row["id"]:
            r["status"] = "running"
            r["updated_at"] = _now_iso()
            break
    _save(op_file, ops3)

    # Pagination cursor
    offset = 0
    if cursor is not None:
        cur = _b64url_load(cursor)
        if not isinstance(cur, dict) or cur.get("v") != 1 or cur.get("account_id") != account_id:
            e = _err("VALIDATION_ERROR", "Invalid cursor.")
            _finalize("failed", resp_obj={"error": e["error"]}, err_msg=e["error"]["message"], http_status=400)
            return e
        if cur.get("sort") != sort or cur.get("order") != order:
            e = _err("VALIDATION_ERROR", "Cursor sort/order does not match request.")
            _finalize("failed", resp_obj={"error": e["error"]}, err_msg=e["error"]["message"], http_status=400)
            return e
        if not isinstance(cur.get("offset"), int) or cur.get("offset") < 0:
            e = _err("VALIDATION_ERROR", "Invalid cursor offset.")
            _finalize("failed", resp_obj={"error": e["error"]}, err_msg=e["error"]["message"], http_status=400)
            return e
        offset = cur["offset"]

    # Read + filter cached inventory
    rows = _load("cf_d1_databases_and_queries.json")
    out = []
    for r in rows:
        if r.get("account_id") != account_id:
            continue
        if r.get("entity_type") != "database":
            continue
        if database_id is not None and r.get("database_id") != database_id:
            continue
        if database_name is not None and r.get("database_name") != database_name:
            continue
        if status is not None and r.get("status") != status:
            continue
        out.append(r)

    # Sort
    reverse = (order == "desc")

    def _sort_key(r):
        v = r.get(sort)
        if sort in ("updated_at", "created_at"):
            dt = _parse_dt(v)
            # Put invalid/missing at end for asc, start for desc
            if dt is None:
                return (1, datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))
            return (0, dt)
        else:
            if v is None:
                return (1, "")
            if not isinstance(v, str):
                v = str(v)
            return (0, v)

    out.sort(key=_sort_key, reverse=reverse)

    total = len(out)
    if offset > total:
        offset = total

    page = out[offset: offset + limit]
    next_cursor = None
    has_more = (offset + limit) < total
    if has_more:
        next_cursor = _b64url_json({"v": 1, "account_id": account_id, "sort": sort, "order": order, "offset": offset + limit})

    resp = {
        "databases": page,
        "total": total,
        "limit": limit,
        "cursor": next_cursor,
        "has_more": has_more,
        "sort": sort,
        "order": order,
    }

    # Succeeded
    _finalize("succeeded", resp_obj={
        "total": total,
        "returned": len(page),
        "has_more": has_more,
        "cursor": next_cursor,
    }, err_msg=None, http_status=200)

    return resp
